function TypographyField( { field, value, onChange, fontsData } ) {
	const obj = value && typeof value === 'object' ? value : {};
	const def = field && field.default && typeof field.default === 'object' ? field.default : {};

	const setValues = ( patch ) => onChange( { ...obj, ...patch } );
	const setKey = ( k, v ) => setValues( { [ k ]: v } );

	const fontFamily = getString( obj[ 'font-family' ] );
	const variant = getString( obj.variant );

	const fontsIndex = useMemo( () => {
		const out = { googleByFamily: {}, variantsLabel: {} };
		if ( fontsData && fontsData.google && Array.isArray( fontsData.google ) ) {
			for ( const f of fontsData.google ) {
				if ( f && f.family ) out.googleByFamily[ String( f.family ) ] = f;
			}
		}
		if ( fontsData && fontsData.variants && typeof fontsData.variants === 'object' ) {
			out.variantsLabel = fontsData.variants;
		}
		return out;
	}, [ fontsData ] );

	const getVariantsForFamily = ( family ) => {
		let variants = [ '', 'regular', 'italic', '700', '700italic' ];

		if ( family && fontsIndex.googleByFamily[ family ] && Array.isArray( fontsIndex.googleByFamily[ family ].variants ) ) {
			variants = fontsIndex.googleByFamily[ family ].variants;
		}

		if (
			field &&
			field.choices &&
			field.choices.fonts &&
			field.choices.fonts.variants &&
			field.choices.fonts.variants[ family ] &&
			Array.isArray( field.choices.fonts.variants[ family ] )
		) {
			variants = field.choices.fonts.variants[ family ];
		}

		return variants;
	};

	const fontOptions = useMemo( () => {
		const opts = [
			{ value: '', label: __( 'Default browser font-family', 'xstore' ) },
			{ value: 'initial', label: 'initial' },
			{ value: 'inherit', label: 'inherit' },
		];

		if ( fontsData && Array.isArray( fontsData.standard ) ) {
			for ( const f of fontsData.standard ) {
				if ( ! f || ! f.stack ) continue;
				opts.push( { value: String( f.stack ), label: String( f.label || f.stack ) } );
			}
		}
		if ( fontsData && Array.isArray( fontsData.google ) ) {
			for ( const f of fontsData.google ) {
				if ( ! f || ! f.family ) continue;
				opts.push( { value: String( f.family ), label: String( f.family ) } );
			}
		}

		if ( fontFamily && ! opts.some( ( o ) => o.value === fontFamily ) ) {
			opts.push( { value: fontFamily, label: fontFamily } );
		}

		const seen = new Set();
		return opts.filter( ( o ) => {
			if ( seen.has( o.value ) ) return false;
			seen.add( o.value );
			return true;
		} );
	}, [ fontsData, fontFamily ] );

	const variantOptions = useMemo( () => {
		const vars = getVariantsForFamily( fontFamily );
		const opts = ( Array.isArray( vars ) ? vars : [] ).map( ( v ) => ( {
			value: String( v ),
			label: fontsIndex.variantsLabel[ v ] ? String( fontsIndex.variantsLabel[ v ] ) : String( v || '' ),
		} ) );

		if ( variant && ! opts.some( ( o ) => o.value === variant ) ) {
			opts.push( { value: variant, label: variant } );
		}

		const seen = new Set();
		return opts.filter( ( o ) => {
			if ( seen.has( o.value ) ) return false;
			seen.add( o.value );
			return true;
		} );
	}, [ fontFamily, variant, fontsIndex.variantsLabel ] );

	const applyVariant = ( nextVariant ) => {
		const v = getString( nextVariant );

		let fontWeight = '';
		let fontStyle = '';
		if ( v ) {
			const digits = v.match( /\d/g );
			fontWeight = digits && digits.length ? digits.join( '' ) : ( v === 'regular' || v === 'italic' ? '400' : '400' );
			fontStyle = v.includes( 'italic' ) ? 'italic' : 'normal';
		}

		setValues( {
			variant: v,
			'font-weight': fontWeight,
			'font-style': fontStyle,
		} );
	};

	const onFamilyChange = ( nextFamily ) => {
		const fam = getString( nextFamily );

		if ( fam === '' || fam === 'inherit' || fam === 'initial' ) {
			setValues( {
				'font-family': fam,
				variant: '',
				'font-weight': '',
				'font-style': '',
			} );
			return;
		}

		const vars = getVariantsForFamily( fam );
		const list = Array.isArray( vars ) ? vars.map( ( x ) => String( x ) ) : [];
		let nextVariantVal = variant;
		if ( list.length > 0 && ! list.includes( nextVariantVal ) ) {
			nextVariantVal = list.includes( 'regular' ) ? 'regular' : list[ 0 ];
		}

		setValues( { 'font-family': fam } );
		if ( nextVariantVal !== variant ) {
			applyVariant( nextVariantVal );
		}
	};

	const showVariant =
		typeof def.variant !== 'undefined' &&
		def.variant !== false &&
		fontFamily !== '' &&
		fontFamily !== 'inherit' &&
		fontFamily !== 'initial' &&
		variantOptions.length > 1;

	return (
		<div style={ { display: 'grid', gap: 12 } }>
			{ typeof def[ 'font-family' ] !== 'undefined' ? (
				<ComboboxControl
					label={ __( 'Font Family', 'xstore' ) }
					value={ fontFamily }
					options={ fontOptions }
					onChange={ onFamilyChange }
				/>
			) : null }

			{ showVariant ? (
				<ComboboxControl
					label={ __( 'Variant', 'xstore' ) }
					value={ variant }
					options={ variantOptions }
					onChange={ ( v ) => applyVariant( v ) }
				/>
			) : null }

			{ typeof def[ 'font-size' ] !== 'undefined' ? (
				<TextControl
					label={ __( 'Font Size', 'xstore' ) }
					value={ getString( obj[ 'font-size' ] ) }
					onChange={ ( v ) => setKey( 'font-size', v ) }
				/>
			) : null }

			{ typeof def[ 'line-height' ] !== 'undefined' ? (
				<TextControl
					label={ __( 'Line Height', 'xstore' ) }
					value={ getString( obj[ 'line-height' ] ) }
					onChange={ ( v ) => setKey( 'line-height', v ) }
				/>
			) : null }

			{ typeof def[ 'letter-spacing' ] !== 'undefined' ? (
				<TextControl
					label={ __( 'Letter Spacing', 'xstore' ) }
					value={ getString( obj[ 'letter-spacing' ] ) }
					onChange={ ( v ) => setKey( 'letter-spacing', v ) }
				/>
			) : null }

			{ typeof def[ 'word-spacing' ] !== 'undefined' ? (
				<TextControl
					label={ __( 'Word Spacing', 'xstore' ) }
					value={ getString( obj[ 'word-spacing' ] ) }
					onChange={ ( v ) => setKey( 'word-spacing', v ) }
				/>
			) : null }

			{ typeof def[ 'text-transform' ] !== 'undefined' ? (
				<SelectControl
					label={ __( 'Text Transform', 'xstore' ) }
					value={ getString( obj[ 'text-transform' ] ) }
					options={ [
						{ value: '', label: '' },
						{ value: 'none', label: __( 'None', 'xstore' ) },
						{ value: 'capitalize', label: __( 'Capitalize', 'xstore' ) },
						{ value: 'uppercase', label: __( 'Uppercase', 'xstore' ) },
						{ value: 'lowercase', label: __( 'Lowercase', 'xstore' ) },
						{ value: 'initial', label: __( 'Initial', 'xstore' ) },
						{ value: 'inherit', label: __( 'Inherit', 'xstore' ) },
					] }
					onChange={ ( v ) => setKey( 'text-transform', v ) }
				/>
			) : null }

			{ typeof def[ 'text-decoration' ] !== 'undefined' ? (
				<SelectControl
					label={ __( 'Text Decoration', 'xstore' ) }
					value={ getString( obj[ 'text-decoration' ] ) }
					options={ [
						{ value: '', label: '' },
						{ value: 'none', label: __( 'None', 'xstore' ) },
						{ value: 'underline', label: __( 'Underline', 'xstore' ) },
						{ value: 'overline', label: __( 'Overline', 'xstore' ) },
						{ value: 'line-through', label: __( 'Line-Through', 'xstore' ) },
						{ value: 'initial', label: __( 'Initial', 'xstore' ) },
						{ value: 'inherit', label: __( 'Inherit', 'xstore' ) },
					] }
					onChange={ ( v ) => setKey( 'text-decoration', v ) }
				/>
			) : null }

			{ typeof def.color !== 'undefined' && def.color !== false ? (
				<div>
					<div style={ { fontWeight: 600, marginBottom: 6 } }>{ __( 'Color', 'xstore' ) }</div>
					<ColorField value={ obj.color } onChange={ ( v ) => setKey( 'color', v ) } allowAlpha={ false } />
				</div>
			) : null }

			{ Object.keys( obj )
				.filter(
					( k ) =>
						! [
							'font-family',
							'variant',
							'font-size',
							'line-height',
							'letter-spacing',
							'word-spacing',
							'text-transform',
							'text-decoration',
							'color',
							'font-weight',
							'font-style',
							'font-backup',
							'font_backup',
						].includes( k )
				)
				.map( ( k ) => (
					<TextControl key={ k } label={ k.replace( /[-_]/g, ' ' ) } value={ getString( obj[ k ] ) } onChange={ ( v ) => setKey( k, v ) } />
				) ) }
		</div>
	);
}

function SortableField( { field, value, onChange } ) {
	const choices = field.choices || {};
	const selected = Array.isArray( value ) ? [ ...value ] : [];
	const remaining = Object.keys( choices ).filter( ( k ) => ! selected.includes( k ) );
	const [ toAdd, setToAdd ] = useState( remaining[ 0 ] || '' );

	const move = ( i, dir ) => {
		const j = i + dir;
		if ( j < 0 || j >= selected.length ) return;
		const next = [ ...selected ];
		const tmp = next[ i ];
		next[ i ] = next[ j ];
		next[ j ] = tmp;
		onChange( next );
	};

	const remove = ( i ) => {
		const next = [ ...selected ];
		next.splice( i, 1 );
		onChange( next );
	};

	const add = () => {
		if ( ! toAdd ) return;
		const next = [ ...selected, toAdd ];
		onChange( next );
		const rem2 = Object.keys( choices ).filter( ( k ) => ! next.includes( k ) );
		setToAdd( rem2[ 0 ] || '' );
	};

	return (
		<div>
			<div style={ { display: 'grid', gap: 8 } }>
				{ selected.map( ( k, i ) => (
					<div key={ k } className="xstoreOptInlineRow">
						<div style={ { minWidth: 240 } }>{ String( choices[ k ] || k ) }</div>
						<Button variant="secondary" onClick={ () => move( i, -1 ) }>↑</Button>
						<Button variant="secondary" onClick={ () => move( i, 1 ) }>↓</Button>
						<Button variant="tertiary" isDestructive onClick={ () => remove( i ) }>
							{ __( 'Remove', 'xstore' ) }
						</Button>
					</div>
				) ) }
			</div>
			<div className="xstoreOptInlineRow" style={ { marginTop: 10, alignItems: 'flex-end' } }>
				<SelectControl
					label={ __( 'Add element', 'xstore' ) }
					value={ toAdd }
					options={ remaining.map( ( k ) => ( { value: k, label: String( choices[ k ] || k ) } ) ) }
					onChange={ ( v ) => setToAdd( v ) }
				/>
				<Button variant="primary" onClick={ add } disabled={ ! toAdd }>
					{ __( 'Add', 'xstore' ) }
				</Button>
			</div>
		</div>
	);
}

function RepeaterField( { field, value, onChange } ) {
	const list = Array.isArray( value ) ? value : [];
	const subFields = field.fields || {};
	const rowLabel = field.row_label || {};
	const buttonLabel = field.button_label || __( 'Add new item', 'xstore' );
	const [ openRows, setOpenRows ] = useState( {} );

	const isOpen = ( idx ) => !! openRows[ idx ];
	const toggleOpen = ( idx ) => setOpenRows( ( prev ) => ( { ...prev, [ idx ]: ! prev[ idx ] } ) );

	const setItem = ( idx, nextItem ) => {
		const next = [ ...list ];
		next[ idx ] = nextItem;
		onChange( next );
	};

	const addItem = () => {
		const item = {};
		for ( const key of Object.keys( subFields ) ) {
			const f = subFields[ key ] || {};
			item[ key ] = typeof f.default !== 'undefined' ? f.default : '';
		}
		setOpenRows( ( prev ) => ( { ...prev, [ list.length ]: true } ) );
		onChange( [ ...list, item ] );
	};

	const removeItem = ( idx ) => {
		const next = [ ...list ];
		next.splice( idx, 1 );
		setOpenRows( ( prev ) => {
			const out = {};
			for ( const k of Object.keys( prev ) ) {
				const i = Number( k );
				if ( Number.isNaN( i ) ) continue;
				if ( i === idx ) continue;
				out[ i > idx ? i - 1 : i ] = prev[ i ];
			}
			return out;
		} );
		onChange( next );
	};

	const moveItem = ( idx, dir ) => {
		const j = idx + dir;
		if ( j < 0 || j >= list.length ) return;
		const next = [ ...list ];
		const tmp = next[ idx ];
		next[ idx ] = next[ j ];
		next[ j ] = tmp;
		setOpenRows( ( prev ) => {
			const out = { ...prev };
			const a = !! out[ idx ];
			const b = !! out[ j ];
			out[ idx ] = b;
			out[ j ] = a;
			return out;
		} );
		onChange( next );
	};

	const getItemTitle = ( item, idx ) => {
		const fallbackBase = rowLabel && rowLabel.value ? String( rowLabel.value ) : __( 'Item', 'xstore' );

		if ( rowLabel && rowLabel.type === 'field' && rowLabel.field && item && typeof item === 'object' && typeof item[ rowLabel.field ] !== 'undefined' ) {
			const raw = getString( item[ rowLabel.field ] );
			if ( raw ) {
				const sf = subFields[ rowLabel.field ] || {};
				const t = sf.type || '';
				const choices = sf.choices || {};
				if ( ( t === 'select' || t === 'radio' || t === 'radio-image' ) && choices && typeof choices === 'object' && typeof choices[ raw ] !== 'undefined' ) {
					return String( choices[ raw ] );
				}
				return raw;
			}
		}

		return `${ fallbackBase } ${ idx + 1 }`;
	};

	const renderSub = ( subKey, subField, itemVal, setVal ) => {
		const t = subField.type || 'text';
		const label = subField.label ? String( subField.label ) : subKey;

		if ( t === 'select' ) {
			return (
				<SelectControl
					label={ label }
					value={ getString( itemVal ) }
					options={ toOptions( subField.choices || {} ) }
					onChange={ ( v ) => setVal( v ) }
				/>
			);
		}

		if ( t === 'checkbox' ) {
			return <CheckboxControl label={ label } checked={ !! itemVal } onChange={ ( v ) => setVal( !! v ) } />;
		}

		if ( t === 'image' ) {
			return (
				<div>
					<div style={ { fontWeight: 600, marginBottom: 6 } }>{ label }</div>
					<ImageField value={ itemVal } onChange={ setVal } />
				</div>
			);
		}

		return <TextControl label={ label } value={ getString( itemVal ) } onChange={ ( v ) => setVal( v ) } />;
	};

	return (
		<div>
			{ list.map( ( item, idx ) => {
				const itemObj = item && typeof item === 'object' ? item : {};
				const title = getItemTitle( itemObj, idx );
				const open = isOpen( idx );

				return (
					<div key={ idx } className="xstoreOptRepeaterItem">
						<div
							className="xstoreOptRepeaterHeader"
							role="button"
							tabIndex={ 0 }
							onClick={ () => toggleOpen( idx ) }
							onKeyDown={ ( e ) => {
								if ( e.key === 'Enter' || e.key === ' ' ) toggleOpen( idx );
							} }
						>
							<div className="xstoreOptRepeaterTitle">
								<span className={ `dashicons ${ open ? 'dashicons-arrow-up-alt2' : 'dashicons-arrow-down-alt2' }` } />
								<span>{ title }</span>
							</div>
							<div className="xstoreOptInlineRow" onClick={ ( e ) => e.stopPropagation() }>
								<Button variant="secondary" onClick={ () => moveItem( idx, -1 ) }>↑</Button>
								<Button variant="secondary" onClick={ () => moveItem( idx, 1 ) }>↓</Button>
								<Button variant="tertiary" isDestructive onClick={ () => removeItem( idx ) }>
									{ __( 'Remove', 'xstore' ) }
								</Button>
							</div>
						</div>
						{ open ? (
							<div className="xstoreOptRepeaterGrid">
								{ Object.keys( subFields ).map( ( subKey ) => {
									const sf = subFields[ subKey ] || {};
									return (
										<div key={ subKey }>
											{ renderSub(
												subKey,
												sf,
												itemObj[ subKey ],
												( nv ) => setItem( idx, { ...itemObj, [ subKey ]: nv } )
											) }
										</div>
									);
								} ) }
							</div>
						) : null }
					</div>
				);
			} ) }
			<Button variant="primary" onClick={ addItem }>{ buttonLabel }</Button>
		</div>
	);
}

function FieldControl( { field, value, onChange, fontsData } ) {
	const type = field.type;
	const v = typeof value === 'undefined' ? field.default : value;

	if ( type === 'toggle' ) {
		return <ToggleControl checked={ toBoolean( v ) } onChange={ ( x ) => onChange( x ? 1 : 0 ) } />;
	}

	if ( type === 'checkbox' ) {
		return <CheckboxControl checked={ toBoolean( v ) } onChange={ ( x ) => onChange( !! x ) } />;
	}

	if ( type === 'multicheck' ) {
		const choices = field.choices || {};
		const keys = Object.keys( choices );
		const selected = new Set( toStringArray( v ) );

		return (
			<div className="xstoreOptMulticheckBox">
				{ keys.map( ( key ) => (
					<CheckboxControl
						key={ key }
						label={ String( choices[ key ] || key ) }
						checked={ selected.has( key ) }
						onChange={ ( isChecked ) => {
							const next = new Set( toStringArray( v ) );
							if ( isChecked ) next.add( key );
							else next.delete( key );

							onChange( keys.filter( ( k ) => next.has( k ) ) );
						} }
					/>
				) ) }
			</div>
		);
	}

	if ( type === 'slider' || type === 'number' ) {
		const min = field.choices && typeof field.choices.min !== 'undefined' ? Number( field.choices.min ) : undefined;
		const max = field.choices && typeof field.choices.max !== 'undefined' ? Number( field.choices.max ) : undefined;
		const step = field.choices && typeof field.choices.step !== 'undefined' ? Number( field.choices.step ) : 1;

		return (
			<RangeControl
				value={ v === '' ? undefined : Number( v ) }
				min={ min }
				max={ max }
				step={ step }
				onChange={ ( x ) => onChange( x ) }
			/>
		);
	}

	if ( type === 'select' ) {
		const isMulti = Number( field && field.multiple ? field.multiple : 0 ) > 1;
		if ( isMulti ) {
			return <MultiSelectField field={ field } value={ v } onChange={ ( x ) => onChange( x ) } />;
		}
		return <SelectControl value={ getString( v ) } options={ toOptions( field.choices ) } onChange={ ( x ) => onChange( x ) } />;
	}

	if ( type === 'radio-buttonset' ) {
		const opts = toOptions( field.choices );
		return (
			<div className="xstoreOptInlineRow">
				{ opts.map( ( o ) => (
					<Button
						key={ o.value }
						variant={ getString( v ) === o.value ? 'primary' : 'secondary' }
						onClick={ () => onChange( o.value ) }
						aria-label={ ( o.label || o.value ) && String( o.label || o.value ) }
						className={ ! String( o.label || '' ).trim() && inferDashiconForChoice( o.value ) ? 'xstoreOptButtonsetBtn isIcon' : undefined }
					>
						{ String( o.label || '' ).trim() ? (
							o.label
						) : inferDashiconForChoice( o.value ) ? (
							<span className={ `dashicons ${ inferDashiconForChoice( o.value ) }` } aria-hidden="true" />
						) : (
							o.value
						) }
					</Button>
				) ) }
			</div>
		);
	}

	if ( type === 'radio-image' ) {
		const choices = field.choices || {};
		return (
			<div className="xstoreOptRadioImageGrid">
				{ Object.keys( choices ).map( ( k ) => {
					const src = String( choices[ k ] || '' );
					const active = getString( v ) === k;
					return (
						<button
							key={ k }
							type="button"
							className={ `xstoreOptRadioImageBtn${ active ? ' isActive' : '' }` }
							onClick={ () => onChange( k ) }
						>
							<img src={ src } alt={ k } />
						</button>
					);
				} ) }
			</div>
		);
	}

	if ( type === 'color' ) {
		const allowAlpha = !! ( field.choices && field.choices.alpha );
		return <ColorField value={ v } onChange={ onChange } allowAlpha={ allowAlpha } />;
	}

	if ( type === 'kirki-wcag-tc' ) {
		return <ColorField value={ v } onChange={ onChange } allowAlpha={ false } />;
	}
	if ( type === 'image' ) return <ImageField value={ v } onChange={ onChange } />;
	if ( type === 'upload' ) return <UploadField value={ v } onChange={ onChange } />;
	if ( type === 'dimensions' ) return <DimensionsField field={ field } value={ v } onChange={ onChange } />;
	if ( type === 'multicolor' ) return <MulticolorField field={ field } value={ v } onChange={ onChange } />;
	if ( type === 'background' ) return <BackgroundField value={ v } onChange={ onChange } />;
	if ( type === 'typography' ) return <TypographyField field={ field } value={ v } onChange={ onChange } fontsData={ fontsData } />;
	if ( type === 'sortable' ) return <SortableField field={ field } value={ v } onChange={ onChange } />;
	if ( type === 'repeater' ) return <RepeaterField field={ field } value={ v } onChange={ onChange } />;

	if ( type === 'code' ) {
		if ( isThemeCustomCssSetting( field.setting ) && codeEditorSettings ) {
			return <ThemeCustomCssCodeEditor value={ getString( v ) } onChange={ ( x ) => onChange( x ) } />;
		}
		return <TextareaControl value={ getString( v ) } onChange={ ( x ) => onChange( x ) } />;
	}

	if ( type === 'editor' ) {
		return <TinyMceField field={ field } value={ getString( v ) } onChange={ ( x ) => onChange( x ) } />;
	}

	if ( type === 'textarea' || type === 'etheme-textarea' ) {
		return <TextareaControl value={ getString( v ) } onChange={ ( x ) => onChange( x ) } />;
	}

	return <TextControl value={ getString( v ) } onChange={ ( x ) => onChange( x ) } />;
}

function App() {
	const [ loading, setLoading ] = useState( true );
	const [ schema, setSchema ] = useState( null );
	const [ values, setValues ] = useState( {} );
	const [ dirty, setDirty ] = useState( {} );
	const [ activeSection, setActiveSection ] = useState( boot.tab || '' );
	const [ search, setSearch ] = useState( '' );
	const [ searchMatches, setSearchMatches ] = useState( null );
	const [ isSearching, setIsSearching ] = useState( false );
	const [ notice, setNotice ] = useState( null );
	const [ collapsedGroups, setCollapsedGroups ] = useState( {} );
	const [ fontsData, setFontsData ] = useState( null );
	const [ isExporting, setIsExporting ] = useState( false );
	const [ isImporting, setIsImporting ] = useState( false );
	const [ importJsonText, setImportJsonText ] = useState( '' );
	const [ isSaving, setIsSaving ] = useState( false );
	const [ isConfirmResetAllOpen, setIsConfirmResetAllOpen ] = useState( false );

	const [headerLogoHtml, setHeaderLogoHtml] = useState('');
	const [switcherHtml, setSwitcherHtml] = useState('');
	const [footerHtml, setFooterHtml] = useState('');

	const [ colorMode, setColorMode ] = useState( null );
	const [ themeLinks, setThemeLinks ] = useState( null );
	const mainRef = useRef( null );
	const actionsRef = useRef( null );
	const [ actionsLayout, setActionsLayout ] = useState( { mode: 'fixed', left: 0, width: 0 } );
	const searchSeqRef = useRef( 0 );

	const effectiveValues = useMemo( () => ( { ...values, ...dirty } ), [ values, dirty ] );
	const isDirty = useMemo( () => Object.keys( dirty ).length > 0, [ dirty ] );

	useEffect( () => {
		setLoading( true );
		Promise.all( [
			apiFetch( { path: '/xstore-options/v1/schema' } ),
			apiFetch( { path: '/xstore-options/v1/values' } ),
			apiFetch( { path: '/xstore-options/v1/fonts' } ).catch( () => null ),
		] )
			.then( ( [ s, v, f ] ) => {
				setSchema( s );
				setValues( v && v.values ? v.values : {} );
				setFontsData( f );
				setLoading( false );

				const sections = s && s.sections ? s.sections : [];
				if ( sections.length ) {
					const initial = boot.tab && sections.find( ( sec ) => sec.id === boot.tab ) ? boot.tab : sections[ 0 ].id;
					setActiveSection( initial );

					const panelsById = s && s.panelsById ? s.panelsById : {};
					const collapsedInit = {};

					for ( const pid of Object.keys( panelsById ) ) {
						collapsedInit[ pid ] = true;
					}

					const activeSec = sections.find( ( sec ) => sec && sec.id === initial );
					if ( activeSec && activeSec.panel ) {
						let pid = String( activeSec.panel );
						while ( pid ) {
							collapsedInit[ pid ] = false;
							pid = panelsById[ pid ] && panelsById[ pid ].panel ? String( panelsById[ pid ].panel ) : '';
						}
					}

					setCollapsedGroups( collapsedInit );
				}
			} )
			.catch( ( e ) => {
				setLoading( false );
				const status = getStatusFromError( e );
				if ( isInvalidJsonError( e ) || status === 401 || status === 403 ) {
					const target = ( boot && boot.legacyUrl )
						? boot.legacyUrl
						: ( boot && boot.customizerUrl )
							? boot.customizerUrl
							: getCustomizerUrl();
					window.location.assign( target );
					return;
				}
				setNotice( { status: 'error', text: e && e.message ? e.message : 'Error loading data.' } );
			} );
	}, [] );

	useEffect( () => {
		if ( ! activeSection ) return;
		const url = new URL( window.location.href );
		url.searchParams.set( 'tab', activeSection );
		window.history.replaceState( {}, '', url.toString() );
	}, [ activeSection ] );

	const nav = useMemo( () => {
		const ROOT = '__root__';

		if ( ! schema ) {
			return { rootId: ROOT, childrenByPanel: { [ ROOT ]: [] } };
		}

		const panelsById = schema.panelsById || {};
		const sections = schema.sections || [];

		const children = {};
		const ensure = ( pid ) => {
			if ( ! children[ pid ] ) children[ pid ] = [];
			return children[ pid ];
		};

		ensure( ROOT );

		for ( const pid of Object.keys( panelsById ) ) {
			const p = panelsById[ pid ];
			if ( ! p || ! p.id ) continue;
			const parent = p.panel ? String( p.panel ) : ROOT;
			ensure( parent ).push( {
				kind: 'panel',
				id: String( p.id ),
				title: String( p.title || p.id ),
				icon: String( p.icon || '' ),
				priority: Number( p.priority ?? 10 ),
			} );
		}

		for ( const s of sections ) {
			if ( ! s || ! s.id ) continue;
			const parent = s.panel ? String( s.panel ) : ROOT;
			ensure( parent ).push( {
				kind: 'section',
				id: String( s.id ),
				title: String( s.title || s.id ),
				icon: String( s.icon || '' ),
				priority: Number( s.priority ?? 10 ),
				panel: String( s.panel || '' ),
			} );
		}

		ensure( ROOT ).push( {
			kind: 'link',
			id: 'live-theme-options',
			title: __( 'Live Theme Options', 'xstore' ),
			icon: 'dashicons-admin-customizer',
			priority: 999998,
			url: getCustomizerUrl(),
		} );

		for ( const pid of Object.keys( children ) ) {
			children[ pid ].sort( ( a, b ) => ( a.priority || 0 ) - ( b.priority || 0 ) );
		}

		const pruned = {};
		const prune = ( pid ) => {
			const items = children[ pid ] || [];
			const out = [];

			for ( const item of items ) {
				if ( item.kind === 'section' || item.kind === 'link' ) {
					out.push( item );
					continue;
				}

				const kids = prune( item.id );
				if ( kids.length ) {
					out.push( item );
				}
			}

			pruned[ pid ] = out;
			return out;
		};

		prune( ROOT );

		return {
			rootId: ROOT,
			childrenByPanel: pruned,
		};
	}, [ schema ] );

	const setValue = ( setting, next ) => setDirty( ( prev ) => ( { ...prev, [ setting ]: next } ) );
	const openSection = ( sectionId ) => {
		setActiveSection( sectionId );

		const q = String( search || '' ).trim();
		if ( q !== '' ) {
			searchSeqRef.current++;
			setSearch( '' );
			setSearchMatches( null );
			setIsSearching( false );
		}
	};

	const getDescendantPanels = (rootId) => {
	  const out = [];
	  const stack = [rootId];
	  while (stack.length) {
	    const id = stack.pop();
	    const kids = nav.childrenByPanel?.[id] || [];
	    const childPanels = kids.filter((k) => k?.kind === "panel").map((k) => k.id);
	    out.push(...childPanels);
	    stack.push(...childPanels);
	  }
	  return out;
	};

	const panelParent = useMemo(() => {
	const parent = {};
	  Object.entries(nav.childrenByPanel || {}).forEach(([panelId, kids]) => {
	    (kids || []).forEach((child) => {
	      if (child?.kind === "panel") parent[child.id] = panelId;
	    });
	  });
	  return parent;
	}, [nav]);

	const panelSiblings = useMemo(() => {
	  const siblings = {};
	  Object.entries(nav.childrenByPanel || {}).forEach(([panelId, kids]) => {
	    const panels = (kids || []).filter((c) => c?.kind === "panel").map((c) => c.id);
	    panels.forEach((id) => (siblings[id] = panels));
	  });
	  return siblings;
	}, [nav]);


	const openParentChain = (map, id) => {
	  let p = panelParent[id];
	  while (p) {
	    map[p] = false;
	    p = panelParent[p];
	  }
	};

	const toggleGroup = (groupId) => {
	  setCollapsedGroups((prev) => {
	    const isCollapsed = prev[groupId] !== undefined ? !!prev[groupId] : true;
	    const willOpen = isCollapsed;

	    const next = { ...prev };

	    openParentChain(next, groupId);

	    const sibs = panelSiblings[groupId] || [];
	    sibs.forEach((sid) => {
	      next[sid] = true;
	    });

	    if (willOpen) {
	      next[groupId] = false;
	    } else {
	      next[groupId] = true;

	      getDescendantPanels(groupId).forEach((cid) => {
	        next[cid] = true;
	      });
	    }

	    return next;
	  });
	};

	const handleInlineEditLink = (e) => {
		const el = e.target?.closest?.(".et_edit");
		if (!el) return;

		e.preventDefault();
		e.stopPropagation();

		var parentId = el.getAttribute("data-parent") || "";
		// const sectionId = el.getAttribute("data-section") || "";

		// 1) Prefer explicit section if provided
		// if (sectionId) {
		// 	openSection(sectionId);
		//
		// 	// optional: make sure parent panel is open too (if it is a panel id)
		// 	if (parentId) {
		// 		setCollapsedGroups((prev) => ({ ...prev, [parentId]: false }));
		// 	}
		// 	return;
		// }

		// 2) If only parent is provided, try:
		// - open section with that id, OR
		// - open first section that belongs to that panel, OR
		// - at least expand panel
		if (parentId) {
			if (['xstore_wishlist', 'xstore_compare', 'xstore_waitlist'].includes(parentId)) {
				parentId = parentId.replace('_', '-');
			}
			const directSection = (schema?.sections || []).find((s) => String(s?.id) === String(parentId));
			if (directSection) {
				openSection(directSection.id);
				return;
			}

			const firstSectionInPanel = (schema?.sections || []).find((s) => String(s?.panel) === String(parentId));
			if (firstSectionInPanel) {
				openSection(firstSectionInPanel.id);
				return;
			}

			// fallback: just expand panel
			setCollapsedGroups((prev) => ({ ...prev, [parentId]: false }));
		}
	};

	useEffect( () => {
		if ( ! schema || ! activeSection ) return;
		const sections = schema.sections || [];
		const sec = sections.find( ( s ) => s && s.id === activeSection );
		if ( ! sec || ! sec.panel ) return;

		const panelsById = schema.panelsById || {};
		setCollapsedGroups( ( prev ) => {
			const next = { ...prev };
			let pid = String( sec.panel );
			while ( pid ) {
				next[ pid ] = false;
				pid = panelsById[ pid ] && panelsById[ pid ].panel ? String( panelsById[ pid ].panel ) : '';
			}
			return next;
		} );
	}, [ activeSection, schema ] );

	const renderNavItems = ( items, depth ) =>
		items.map( ( item ) => {
			if ( item.kind === 'link' ) {
				return (
					<li key={ `link-${ item.id }` } className="xstoreOptNavItem">
						<a href={ item.url } className="xstoreOptGroupTitle" target="_blank" rel="noopener noreferrer">
							{ item.icon ? <span className={ `et-panel-nav-icon dashicons ${ item.icon }` } /> : null }
							<span>{ item.title }</span>
						</a>
					</li>
				);
			}

			if ( item.kind === 'panel' ) {
				const isCollapsed = typeof collapsedGroups[ item.id ] !== 'undefined' ? !! collapsedGroups[ item.id ] : true;
				const kids = nav.childrenByPanel[ item.id ] || [];

				return (
					<li key={ `panel-${ item.id }` } className={ `xstoreOptNavItem xstoreOptNavPanel${ isCollapsed ? '' : ' isOpen' }` }>
						<a
							href="#"
							className="xstoreOptGroupTitle"
							role="button"
							aria-expanded={ ! isCollapsed }
							onClick={ ( e ) => {
								e.preventDefault();
								toggleGroup( item.id );
							} }
							onKeyDown={ ( e ) => {
								if ( e.key === 'Enter' || e.key === ' ' ) {
									e.preventDefault();
									toggleGroup( item.id );
								}
							} }
						>
							{ item.icon ? <span className={ `et-panel-nav-icon dashicons ${ item.icon }` } /> : null }
							<span>{ item.title }</span>
							<span className={`et-panel-nav-icon dashicons ${isCollapsed ? 'dashicons-arrow-down-alt2' : 'dashicons-arrow-up-alt2'} xstoreOptPanelChevron` }
								aria-hidden="true"></span>
						</a>
						{!isCollapsed && kids.length && (
						  <ul>
						    {renderNavItems(kids, depth + 1)}
						  </ul>
						)}
					</li>
				);
			}

			return (
				<li
					key={ `section-${ item.id }` }
					className={ `xstoreOptNavItem${ item.id === activeSection ? ' isActive' : '' }` }
					onClick={ ( e ) => {
						e.preventDefault();
						openSection( item.id );
					} }
				>
					<a href="#" className={`xstoreOptGroupTitle${ item.id === activeSection ? ' active' : '' }`}>
						{ item.icon ? <span className={ `et-panel-nav-icon dashicons ${ item.icon }` } /> : null }
						<span>{ item.title }</span>
					</a>
				</li>
			);
		} );


	useEffect(() => {
	    apiFetch({ path: '/xstore-options/v1/page-colormode', method: 'POST', data: {} }).then((res) => {
	      setColorMode(res);
	    });
	  }, []);

	  useEffect(() => {
	    apiFetch({ path: '/xstore-options/v1/theme-links', method: 'POST', data: {} }).then((res) => {
	      setThemeLinks(res);
	    });
	  }, []);

	useEffect(() => {
	    apiFetch({ path: '/xstore-options/v1/page-logo', method: 'POST', data: {} }).then((res) => {
	      if (res?.success) setHeaderLogoHtml(res.data.html || "");
	    });
	  }, []);

  	useEffect(() => {
	    apiFetch({ path: '/xstore-options/v1/page-switcher', method: 'POST', data: {} }).then((res) => {
	      if (res?.success) setSwitcherHtml(res.data.html || "");
	    });
	  }, []);

	useEffect(() => {
	    apiFetch({ path: '/xstore-options/v1/page-footer', method: 'POST', data: {} }).then((res) => {
	      if (res?.success) setFooterHtml(res.data.html || "");
	    });
	  }, []);

	useEffect( () => {
		if ( ! schema ) return;

		const q = String( search || '' ).trim();
		if ( q === '' || q.length < 3 ) {
			setIsSearching( false );
			setSearchMatches( null );
			return;
		}

		const seq = ++searchSeqRef.current;
		setIsSearching( true );

		const timer = setTimeout( () => {
			apiFetch( { path: `/xstore-options/v1/search?q=${ encodeURIComponent( q ) }&limit=250` } )
				.then( ( res ) => {
					if ( seq !== searchSeqRef.current ) return;
					const matches = res && Array.isArray( res.matches ) ? res.matches : [];
					setSearchMatches( matches );
				} )
				.catch( () => {
					if ( seq !== searchSeqRef.current ) return;
					setSearchMatches( [] );
				} )
				.finally( () => {
					if ( seq !== searchSeqRef.current ) return;
					setIsSearching( false );
				} );
		}, 200 );

		return () => clearTimeout( timer );
	}, [ search, schema ] );

	useLayoutEffect( () => {
		if ( loading ) return;
		let raf = 0;

		const update = () => {
			raf = 0;
			const mainEl = mainRef.current;
			const barEl = actionsRef.current;
			if ( ! mainEl || ! barEl ) return;

			const rect = mainEl.getBoundingClientRect();
			const shouldFix = rect.bottom > window.innerHeight;
			setActionsLayout( {
				mode: shouldFix ? 'fixed' : 'absolute',
				left: Math.round( rect.left ),
				width: Math.round( rect.width ),
			} );
		};

		const onScroll = () => {
			if ( raf ) return;
			raf = window.requestAnimationFrame( update );
		};

		update();
		window.addEventListener( 'scroll', onScroll, { passive: true } );
		window.addEventListener( 'resize', onScroll );
		return () => {
			window.removeEventListener( 'scroll', onScroll );
			window.removeEventListener( 'resize', onScroll );
			if ( raf ) window.cancelAnimationFrame( raf );
		};
	}, [ loading ] );

	const fileToText = ( file ) =>
		new Promise( ( resolve, reject ) => {
			if ( ! file ) return resolve( '' );
			if ( typeof file.text === 'function' ) {
				file.text().then( resolve ).catch( reject );
				return;
			}

			const reader = new FileReader();
			reader.onload = () => resolve( String( reader.result || '' ) );
			reader.onerror = () => reject( reader.error || new Error( 'Read error' ) );
			reader.readAsText( file );
		} );

	const exportOptions = () => {
		if ( isExporting ) return;
		setNotice( null );
		setIsExporting( true );

		apiFetch( { path: '/xstore-options/v1/export' } )
			.then( ( payload ) => {
				const data = payload && payload.values ? payload : { values: payload };
				const json = JSON.stringify( data, null, 2 );
				const blob = new Blob( [ json ], { type: 'application/json;charset=utf-8' } );
				const url = URL.createObjectURL( blob );

				const stamp = String( ( data && data.meta && data.meta.exportedAt ) || new Date().toISOString() ).replace( /[:.]/g, '-' );
				const a = document.createElement( 'a' );
				a.href = url;
				a.download = `xstore-options-${ stamp }.json`;
				document.body.appendChild( a );
				a.click();
				a.remove();
				URL.revokeObjectURL( url );

				setNotice( { status: 'success', text: __( 'Export file downloaded.', 'xstore' ) } );
				window.scrollTo( { top: 0, behavior: 'smooth' } );
			} )
			.catch( ( e ) => {
				setNotice( { status: 'error', text: e && e.message ? e.message : __( 'Export error.', 'xstore' ) } );
				window.scrollTo( { top: 0, behavior: 'smooth' } );
			} )
			.finally( () => setIsExporting( false ) );
	};

	const onPickImportFile = ( e ) => {
		const file = e?.target?.files?.[ 0 ];
		if ( ! file ) {
			setImportJsonText( '' );
			return;
		}

		fileToText( file )
			.then( ( text ) => setImportJsonText( String( text || '' ) ) )
			.catch( () => {
				setImportJsonText( '' );
				setNotice( { status: 'error', text: __( 'Cannot read file.', 'xstore' ) } );
			} );
	};

	const importOptions = () => {
		if ( isImporting ) return;
		if ( ! importJsonText ) {
			setNotice( { status: 'error', text: __( 'Please choose a JSON file first.', 'xstore' ) } );
			window.scrollTo( { top: 0, behavior: 'smooth' } );
			return;
		}
		if ( ! window.confirm( __( 'Import will overwrite existing options. Continue?', 'xstore' ) ) ) return;

		setNotice( null );
		setIsImporting( true );

		let parsed;
		try {
			parsed = JSON.parse( importJsonText );
		} catch ( err ) {
			setIsImporting( false );
			setNotice( { status: 'error', text: __( 'Invalid JSON file.', 'xstore' ) } );
			window.scrollTo( { top: 0, behavior: 'smooth' } );
			return;
		}

		const valuesToImport =
			parsed && typeof parsed === 'object' && ! Array.isArray( parsed ) && parsed.values && typeof parsed.values === 'object'
				? parsed.values
				: parsed;

		if ( ! valuesToImport || typeof valuesToImport !== 'object' || Array.isArray( valuesToImport ) ) {
			setIsImporting( false );
			setNotice( { status: 'error', text: __( 'Invalid import payload.', 'xstore' ) } );
			window.scrollTo( { top: 0, behavior: 'smooth' } );
			return;
		}

		apiFetch( { path: '/xstore-options/v1/import', method: 'POST', data: { values: valuesToImport } } )
			.then( ( r ) => {
				const upd = r && r.updated ? r.updated : {};
				setValues( ( prev ) => ( { ...prev, ...upd } ) );
				setDirty( {} );

				const imported = r && typeof r.imported === 'number' ? r.imported : Object.keys( upd ).length;
				const ignored = r && typeof r.ignored === 'number' ? r.ignored : 0;
				setNotice( {
					status: 'success',
					text:
						ignored > 0
							? __( 'Imported.', 'xstore' ) + ` ${ imported }. ` + __( 'Ignored:', 'xstore' ) + ` ${ ignored }.`
							: __( 'Imported.', 'xstore' ) + ` ${ imported }.`,
				} );
				window.scrollTo( { top: 0, behavior: 'smooth' } );
			} )
			.catch( ( e ) => {
				setNotice( { status: 'error', text: e && e.message ? e.message : __( 'Import error.', 'xstore' ) } );
				window.scrollTo( { top: 0, behavior: 'smooth' } );
			} )
			.finally( () => setIsImporting( false ) );
	};

	const saveChanges = () => {
		if ( ! isDirty || isSaving ) return;
		setNotice( null );
		setIsSaving( true );

		apiFetch( { path: '/xstore-options/v1/save', method: 'POST', data: { changes: dirty } } )
			.then( ( r ) => {
				const upd = r && r.updated ? r.updated : {};
				setValues( ( prev ) => ( { ...prev, ...upd } ) );
				setDirty( {} );
				setNotice( { status: 'success', text: __( 'Changes saved successfully.', 'xstore' ) } );
				window.scrollTo( { top: 0, behavior: 'smooth' } );
			} )
			.catch( ( e ) => {
				setNotice( { status: 'error', text: e && e.message ? e.message : 'Save error.' } );
				window.scrollTo( { top: 0, behavior: 'smooth' } );
			} )
			.finally( () => setIsSaving( false ) );
	};

	const resetSection = () => {
		if ( ! activeSection ) return;
		if ( ! window.confirm( __( 'Reset this section to defaults?', 'xstore' ) ) ) return;
		setNotice( null );

		apiFetch( { path: '/xstore-options/v1/reset-section', method: 'POST', data: { section: activeSection } } )
			.then( ( r ) => {
				const upd = r && r.updated ? r.updated : {};
				setValues( ( prev ) => ( { ...prev, ...upd } ) );
				setDirty( {} );
				setNotice( { status: 'success', text: __( 'Section reset successfully.', 'xstore' ) } );
			} )
			.catch( ( e ) => setNotice( { status: 'error', text: e && e.message ? e.message : 'Reset error.' } ) );
	};

	const resetAll = () => {
		setIsConfirmResetAllOpen( true );
	};

	const doResetAll = () => {
		setNotice( null );

		apiFetch( { path: '/xstore-options/v1/reset-all', method: 'POST', data: {} } )
			.then( ( r ) => {
				const upd = r && r.updated ? r.updated : {};
				setValues( ( prev ) => ( { ...prev, ...upd } ) );
				setDirty( {} );
				setNotice( { status: 'success', text: __( 'All options reset successfully.', 'xstore' ) } );
				setIsConfirmResetAllOpen( false );
			} )
			.catch( ( e ) => setNotice( { status: 'error', text: e && e.message ? e.message : 'Reset error.' } ) );
	};

	if ( loading ) {
		return (
			<div className="xstoreOptLoadingOverlay" aria-busy="true" aria-live="polite">
				<div className="xstoreOptLoadingSpinner" aria-label={ __( 'Loading...', 'xstore' ) } />
			</div>
		);
	}

	if ( ! schema ) {
		return <div style={ { padding: 24 } }>{ __( 'No data.', 'xstore' ) }</div>;
	}

	const currentFields = schema.fieldsBySection && schema.fieldsBySection[ activeSection ] ? schema.fieldsBySection[ activeSection ] : [];
	const sectionObj = ( schema.sections || [] ).find( ( s ) => s.id === activeSection );
	const searchQuery = String( search || '' ).trim();
	const isSearchMode = searchQuery.length >= 3;
	const isImportExportSection = activeSection === 'import_export';

	const activeCallbackValues = (() => {
		if (
			activeSection !== 'single-product-page-wishlist' &&
			activeSection !== 'single-product-page-compare' &&
			activeSection !== 'single-product-page-waitlist'
		) {
			return effectiveValues;
		}

		const out = {};
		for ( const f of currentFields ) {
			const k = f && f.setting ? String( f.setting ) : '';
			if ( ! k ) continue;
			out[ k ] = effectiveValues[ k ];
		}
		return out;
	})();

	const visibleFields = currentFields
		.filter( ( f ) => ! isHiddenField( f ) )
		.filter( ( f ) => isFieldActive( f, activeCallbackValues ) )
		.filter( ( f ) => hasTextMatch( f, search ) );

	const sectionTitleById = (() => {
		const map = {};
		for ( const s of ( schema.sections || [] ) ) {
			if ( s && s.id ) map[ String( s.id ) ] = String( s.title || s.id );
		}
		return map;
	})();

	const searchResultFields = (() => {
		if ( ! isSearchMode || ! schema ) return [];
		if ( ! Array.isArray( searchMatches ) ) return [];

		const out = [];
		const bySetting = schema.fieldsBySetting || {};

		for ( const m of searchMatches ) {
			const setting = m && m.setting ? String( m.setting ) : '';
			if ( ! setting ) continue;
			const field = bySetting[ setting ];
			if ( ! field ) continue;
			if ( isHiddenField( field ) ) continue;
			if ( field.type === 'custom' || field.is_separator ) continue;
			if ( ! isFieldActive( field, effectiveValues ) ) continue;
			out.push( field );
		}

		const sectionPriority = {};
		for ( const s of ( schema.sections || [] ) ) {
			if ( s && s.id ) sectionPriority[ String( s.id ) ] = Number( s.priority ?? 10 );
		}

		out.sort( ( a, b ) => {
			const ap = sectionPriority[ String( a.section || '' ) ] ?? 10;
			const bp = sectionPriority[ String( b.section || '' ) ] ?? 10;
			if ( ap !== bp ) return ap - bp;
			return Number( a.priority ?? 10 ) - Number( b.priority ?? 10 );
		} );

		return out;
	})();

	const searchResultGroups = (() => {
		if ( ! isSearchMode || ! schema ) return [];
		if ( ! Array.isArray( searchResultFields ) || searchResultFields.length === 0 ) return [];

		const groups = [];
		const byId = {};

		for ( const f of searchResultFields ) {
			const secIdRaw = f && f.section ? String( f.section ) : '';
			const secId = secIdRaw || '__other__';
			if ( ! byId[ secId ] ) {
				byId[ secId ] = {
					id: secId,
					title: secIdRaw ? ( sectionTitleById[ secIdRaw ] || secIdRaw ) : __( 'Other', 'xstore' ),
					fields: [],
				};
				groups.push( byId[ secId ] );
			}
			byId[ secId ].fields.push( f );
		}

		return groups;
	})();

	return (
		<>
			<div class="etheme-page-wrapper" data-mode={colorMode}>
				{headerLogoHtml ? (
					<div className="etheme-page-header flex justify-content-between align-items-center">
						<div className={`etheme-logo`} dangerouslySetInnerHTML={ { __html: headerLogoHtml } } />
						{switcherHtml ? (<div className="et_panel-dark-light-switcher" dangerouslySetInnerHTML={ { __html: switcherHtml } } />) : null}
						<div className="etheme-search">
							<i className="etheme-search-icon">
								<svg
									version="1.1"
									xmlns="http://www.w3.org/2000/svg"
									width="1em"
									height="1em"
									viewBox="0 0 32 32"
									fill="currentColor"
								> 
									<path d="M31.712 30.4l-8.224-8.192c2.112-2.464 3.264-5.568 3.264-8.768 0-7.36-5.984-13.376-13.376-13.376-7.36 0-13.344 5.984-13.344 13.344s5.984 13.376 13.376 13.376c3.232 0 6.304-1.152 8.768-3.296l8.224 8.192c0.192 0.192 0.416 0.288 0.64 0.288s0.448-0.096 0.608-0.256c0.192-0.16 0.288-0.384 0.32-0.64 0-0.256-0.096-0.512-0.256-0.672zM24.928 13.44c0 6.336-5.184 11.52-11.552 11.52-6.336 0-11.52-5.184-11.52-11.552 0-6.336 5.184-11.52 11.552-11.52s11.52 5.184 11.52 11.552z"></path>
								</svg>
							</i>
							<span className="spinner">
								<span className="et-loader">
									<svg className="loader-circular" viewBox="25 25 50 50">
										<circle
											className="loader-path"
											cx="50"
											cy="50"
											r="12"
											fill="none"
											strokeWidth="2"
											strokeMiterlimit="10"
										></circle>
									</svg>
								</span>
							</span>
							<input
								type="text"
								className="etheme-options-search form-control"
									placeholder={ __( 'Search for options', 'xstore' ) }
								value={ search }
								onChange={ ( e ) => setSearch( e?.target?.value || '' ) }
							/>
						</div>
					</div>
			      ) : null}
				<div className="xstoreOptApp">
					<aside className="etheme-page-nav xstoreOptSidebar">
						<ul>
							{renderNavItems(nav.childrenByPanel[nav.rootId] || [], 0)}
						</ul>
						<span className="etheme-page-nav-collapser"><span
							className="dashicons dashicons-arrow-left"></span></span>
					</aside>

					<main className="et-row etheme-page-content" ref={mainRef}>
						{isSaving ? (
							<div className="xstoreOptSavingOverlay" aria-busy="true" aria-live="polite">
								<div className="xstoreOptSavingSpinner" aria-label={ __( 'Saving...', 'xstore' ) } />
							</div>
						) : null }
						<div className="xstoreOptContent">
							{ notice ? (
								<Notice status={ notice.status } isDismissible onRemove={ () => setNotice( null ) }>
									{ notice.text }
								</Notice>
							) : null }

							{ isDirty ? (
								<Notice status="warning" isDismissible={ false }>
									{ __( 'You have unsaved changes.', 'xstore' ) }
								</Notice>
							) : null }

							<h1 class="etheme-page-title etheme-page-title-type-2">
								{ isSearchMode ? __( 'Search Results', 'xstore' ) : ( sectionObj ? sectionObj.title : '' ) }
							</h1>

							{ ! isSearchMode && sectionObj && sectionObj.description ? (
								<div
									className="xstoreOptSectionDescription"
									dangerouslySetInnerHTML={ { __html: sectionObj.description } }
								/>
							) : null }

							{ isSearchMode ? (
								<>
									{ isSearching ? (<div className="xstoreOptLoadingOverlay" aria-busy="true" aria-live="polite" style={{marginTop: '100px'}}><div className="xstoreOptLoadingSpinner" aria-label={ __( 'Searching...', 'xstore' ) }></div></div>) : null }
									{ ! isSearching && Array.isArray( searchMatches ) && searchMatches.length === 0 ? (
										<Notice status="warning" isDismissible={ false }>
											{ __( 'No results.', 'xstore' ) }
										</Notice>
									) : null }
									{ searchResultGroups.map( ( g ) => (
										<div key={ `search_group_${ g.id }` }>
											<div class="xstoreOptSearchSectionTitle etheme-page-title etheme-page-title-type-2">{ g.title }</div>
											{ ( g.fields || [] ).map( ( field ) => {
												const setting = field.setting;
												const val = effectiveValues[ setting ];
												const hideTitle = field.type === 'code' && isThemeCustomCssSetting( setting );

												return (
													<div key={ setting } className="xstoreOptField flex align-items-center" data-setting={ setting }>
														{ ! hideTitle ? (
															<div className="xstoreOptFieldMeta">
																<h4 className="xstoreOptFieldLabel et-title">{ field.label || setting }</h4>
																{ field.tooltip ? ( <p className="xstoreOptFieldDesc" onClick={handleInlineEditLink} dangerouslySetInnerHTML={ { __html: field.tooltip } } /> ) : null }
																{ field.description ? ( <p className="xstoreOptFieldDesc" onClick={handleInlineEditLink} dangerouslySetInnerHTML={ { __html: field.description } } /> ) : null }
															</div>
														) : null }
														<p className="xstoreOptFieldControl">
															<FieldControl field={ field } value={ val } onChange={ ( next ) => setValue( setting, next ) } fontsData={ fontsData } />
														</p>
													</div>
												);
											} ) }
										</div>
									) ) }
								</>
							) : (
								isImportExportSection ? (
									<>
										<div className="xstoreOptField flex align-items-center">
											<div className="xstoreOptFieldMeta">
												<h4 className="xstoreOptFieldLabel et-title">{ __( 'Export options', 'xstore' ) }</h4>
												<p className="xstoreOptFieldDesc">{ __( 'Download a JSON backup of all Theme Options.', 'xstore' ) }</p>
											</div>
											<p className="xstoreOptFieldControl">
												<button type="button" className="et-button no-loader" onClick={ exportOptions } disabled={ isExporting }>
													{ isExporting ? __( 'Exporting...', 'xstore' ) : __( 'Export', 'xstore' ) }
												</button>
											</p>
										</div>

										<div className="xstoreOptField flex align-items-center">
											<div className="xstoreOptFieldMeta">
												<h4 className="xstoreOptFieldLabel et-title">{ __( 'Import options', 'xstore' ) }</h4>
												<p className="xstoreOptFieldDesc">
													{ __( 'Upload a previously exported JSON file to overwrite current Theme Options.', 'xstore' ) }
												</p>
											</div>
											<p className="xstoreOptFieldControl">
												<input type="file" accept=".json,application/json" onChange={ onPickImportFile } />
												<br/><br/><button
													type="button"
													className="et-button et-button-grey no-loader"
													onClick={ importOptions }
													disabled={ isImporting }
												>
													{ isImporting ? __( 'Importing...', 'xstore' ) : __( 'Import', 'xstore' ) }
												</button>
											</p>
										</div>
									</>
								) : (
									visibleFields.map( ( field ) => {
										const setting = field.setting;
										const val = effectiveValues[ setting ];
										const hideTitle = field.type === 'code' && isThemeCustomCssSetting( setting );

										if ( field.type === 'custom' || field.is_separator ) {
											const title = String( field.label || '' ).trim();
											if ( ! title ) return null;
											return (
												<div key={ `sep_${ setting }` } className="xstoreOptSearchSectionTitle etheme-page-title etheme-page-title-type-2">
													{ title }
												</div>
											);
										}

										return (
											<div key={ setting } className="xstoreOptField flex align-items-center" data-setting={ setting }>
												{ ! hideTitle ? (
													<div className="xstoreOptFieldMeta">
														<h4 className="xstoreOptFieldLabel et-title">{ field.label || setting }</h4>
														{ field.tooltip ? ( <p className="xstoreOptFieldDesc" onClick={handleInlineEditLink} dangerouslySetInnerHTML={ { __html: field.tooltip } } /> ) : null }
														{ field.description ? ( <p className="xstoreOptFieldDesc" onClick={handleInlineEditLink} dangerouslySetInnerHTML={ { __html: field.description } } /> ) : null }
													</div>
												) : null }
												<p className="xstoreOptFieldControl">
													<FieldControl field={ field } value={ val } onChange={ ( next ) => setValue( setting, next ) } fontsData={ fontsData } />
												</p>
											</div>
										);
									} )
								)
							) }
						</div>

						<div
							ref={ actionsRef }
							className={ `xstoreOptActionsBar${ actionsLayout.mode === 'fixed' ? ' isFixed' : ' isAbsolute' }` }
							style={ actionsLayout.mode === 'fixed' ? { left: actionsLayout.left, width: actionsLayout.width } : undefined }
						>
							<button
								type="button"
								className="et-button no-loader xstoreOptBtnSave"
								onClick={ saveChanges }
								disabled={ ! isDirty || isSaving }
							>
								{ __( 'Save Changes', 'xstore' ) }
							</button>
							<button
								type="button"
								className="et-button et-button-grey no-loader"
								onClick={ resetSection }
								disabled={ isImportExportSection || isSaving }
							>
								{ __( 'Reset Section', 'xstore' ) }
							</button>
							<button type="button" className="et-button et-button-grey no-loader" onClick={ resetAll } disabled={ isSaving }>
								{ __( 'Reset All', 'xstore' ) }
							</button>
							
							<a className="xstoreOptThemeSupport" href={ themeLinks?.support_forum?.link ? themeLinks.support_forum.link : null} target="_blank">
								<svg width="1em" height="1em" viewBox="0 0 10 10" fill="currentColor" xmlns="http://www.w3.org/2000/svg">
	                                <path d="M5 0C2.24284 0 0 2.24284 0 5C0 7.75716 2.24284 10 5 10C7.75716 10 10 7.75716 10 5C10 2.24284 7.75716 0 5 0ZM5 0.833333C7.30631 0.833333 9.16667 2.69369 9.16667 5C9.16667 7.30631 7.30631 9.16667 5 9.16667C2.69369 9.16667 0.833333 7.30631 0.833333 5C0.833333 2.69369 2.69369 0.833333 5 0.833333ZM5 2.5C4.08366 2.5 3.33333 3.25033 3.33333 4.16667H4.16667C4.16667 3.70117 4.53451 3.33333 5 3.33333C5.46549 3.33333 5.83333 3.70117 5.83333 4.16667C5.83333 4.48568 5.62826 4.76888 5.32552 4.86979L5.15625 4.92188C4.81608 5.03418 4.58333 5.3597 4.58333 5.71615V6.25H5.41667V5.71615L5.58594 5.66406C6.22721 5.45085 6.66667 4.84212 6.66667 4.16667C6.66667 3.25033 5.91634 2.5 5 2.5ZM4.58333 6.66667V7.5H5.41667V6.66667H4.58333Z"></path>
	                            </svg>
                            </a>
						</div>
					</main>
				</div>
				{ isConfirmResetAllOpen ? (
					<Modal
						title={ __( 'Reset ALL options to defaults?', 'xstore' ) }
						onRequestClose={ () => setIsConfirmResetAllOpen( false ) }
						shouldCloseOnClickOutside
					>
						<div style={ { display: 'grid', gap: 10 } }>
							<div>
								<p style={ { margin: 0 } }>
									{ __( 'This action will permanently reset all theme options to their default values.', 'xstore' ) }
								</p>
								<p style={ { margin: 0 } }>
									{ __( 'We strongly recommend exporting your current settings before proceeding.', 'xstore' ) }
								</p>
								<p style={ { margin: 0 } }>
									{ __( 'This action cannot be undone.', 'xstore' ) }
								</p>
							</div>

							<div className="xstoreOptInlineRow" style={ { justifyContent: 'flex-end' } }>
								<Button variant="secondary" onClick={ exportOptions } disabled={ isExporting }>
									{ isExporting ? __( 'Exporting...', 'xstore' ) : __( 'Export', 'xstore' ) }
								</Button>
								<Button variant="tertiary" onClick={ () => setIsConfirmResetAllOpen( false ) }>
									{ __( 'Cancel', 'xstore' ) }
								</Button>
								<Button variant="primary" isDestructive onClick={ doResetAll }>
									{ __( 'Reset all', 'xstore' ) }
								</Button>
							</div>
						</div>
					</Modal>
				) : null }
				{footerHtml ? (
					<div dangerouslySetInnerHTML={ { __html: footerHtml } } />
				) : null}
			</div>
		</>
	);
}

const root = document.getElementById( 'xstore-options-admin-root' );
if ( root ) {
	render( <App />, root );
}


